   "hitokoto": "作品集の見せ場や、宇宙の大きさを一気に見せたい時に。真っ暗な画面の点1つ（太陽）から、一度も切らずに引いていく横長45秒。点は星の群れになり、天の川銀河の渦になり、その渦が1つの点になって、点が無数に増える（点ひとつが、銀河ひとつ）。途中で一度だけ、その1つへ飛び込む。網の目のように連なる銀河、観測できる宇宙の全体まで引いたら、時間を巻き戻して全部が1点に集まり、もう一度広がって終わる。約473万個の光の粒だけで描き、左下の物差しがけたの替わるたびに1音鳴る。数字は広く知られた概数。粒も音もコードで作っている。",
