   "hitokoto": "「連絡の道具は、こう変わってきた」を15秒で解説したい時に。授業や勉強会の導入に使える歴史の教材。世界のお手本の棚にある、RPA さんの「検索の歴史を15秒の年表に」（年号を叩きつけ、線画を描き足す）に寄せて作った、おけもん版の15秒。生成りの紙の上を朱色の糸が1本走り、1663年の飛脚、1871年の切手をはった手紙、1890年の電話、1968年のポケベル、1971年の＠つきのメール、いまのスマホのメッセージへ。年号がドンと落ちるたびに、前の線画が次の線画へ変身し、糸は道・手紙の軌跡・電話のコード・電波・＠・ハートに姿を変える。最後は6つの線画が1本の糸に並んで「伝えたい気持ちは、ずっと同じ。」。自分の仕事や趣味の「〇〇の歴史」に置きかえても作れる。線画も音もコードで作った（素材なし）。",
