   "hitokoto": "毎朝のイベントを、まだ知らない人に紹介したい時に。モデル違いの比べっこの1本で、同じ注文書と素材を Codex に渡して61分でできた26秒。舞台は朝の窓辺の机。スマホの「おはよう」から朝日が広がり、3人が机の上で案内して、最後に空いた椅子がこちらを向く。渡した土台の描画が動かない環境だったので、Codex が自分で平面の描き方に切り替えて作った。音も Codex が一から作っている。",
