   "prompt": {
    "text": "あなたは、いまできる最高のモーショングラフィックを作る作り手です。作業フォルダの中だけで作業し、作った物はすべてそこに置いてください。\n\n## 頼まれていること\nあなたが今できる最高のモーショングラフィックで、見た人が思わず「すごい」と声に出す1本を作ってください。\nいま世界中で話題の「AIが本気で作るモーショングラフィック」です。あなたの腕前を、出し惜しみせず全力で証明してください。\n\n## ゴール\n見た人が「明日の朝、のぞいてみようかな」と声に出す、20〜30秒・音つきの1本。用途は、コミュニティの中で、朝のAI勉強会をまだ知らない初心者さんに見せる紹介。「すごい」は派手さではなく、この用途で見る人が声を出すこと。テイストはあなたが決める。\n\n## 事実（画面に出してよいこと）\n- 名前：朝のAI勉強会\n- 毎朝 7:00〜7:30、oVice で、AIの最新情報を初心者向けにやさしく解説\n- スマホから聞き専OK（聞くだけの参加でいい）\n- アーカイブ動画あり\n- これ以外の数字・日付・肩書きは画面に出さない。作者名やクレジットも出さない\n\n## 出発点の案（もっと声が出る形を思いついたら、理由を1行残して変えてよい。順番も中身もあなたが決める）\nまだ暗い朝6:59、スマホの画面にひとつだけ「おはよう」が灯る。7:00 の合図でその一粒から朝日が昇り、今日のAIニュースが1枚ずつ目の前に立ち上がって、聞いているだけの人の所へも届く。最後に空いている席がひとつ、「明日の7:00、oViceで」。舞台は1つ（朝の、まだ静かな場所）。\n\n## 守るもの（3つ）\n事実（時刻・場所・名前）を正しく／案内役の3人がかわいく見える（渡した絵柄のまま。描き直さない）／音が絵と同じ時刻表を読んでいる（ずれていない）\n\n## 使える素材（作業フォルダに入れて渡した物。使うかどうか・どう使うかは自由）\n- 案内役3人の立ち絵（背景が透明の画像。手を振る・ジャンプ・指さす・話す・バンザイ）\n- 曲（約64秒。一部を切って使ってよい。自分で音を作ってもよい）\n- 土台：紙の世界を立体で描くための部品と、1コマずつ書き出す道具（使ってもよいし、別の方法でもよい）\n\n## 今回出す物\n1. 最初の8〜10秒の試し動画（音つき・小さめ）とコマ一覧。ここで一度、自分の目で見る（止まって見えないか・舞台が1つに見えるか・3人がかわいいか・音が絵と合っているか）。直してから全編へ。\n2. 全編（20〜30秒・音つき）と、コマ一覧（1秒ごと）。\n3. 時間割・動かし方・考えたことと捨てた案とうまくいかなかった所の記録。\n\n## 出す前に\n自分の目で見る（コマ一覧と、動きは数コマ続けて）。朝の空気が本当にその場にあるように見えるか、3人がかわいいか、音が打点で盛り上がるか。数字の検査（止まっているコマ・音量・読めない字・黒いコマ・事実の誤り）は事故を拾うためだけに使う。直したくなる所が尽きなくても、全編が通ったら一度書き出して出す。",
    "note": "アプリの「これをお手本に作る」で作った注文書をそのまま、Claude Code（Opus 5.5）に貼って作りました。お手本の動画は、形と動きの参考に見ています。動画への書き出しには HyperFrames（HTMLを動画にする道具）を使いました"
   },
