   "aspect": "16:9",
   "hitokoto": "掲げている合言葉を、線と文字だけで静かに上品に見せたい時に。世界のお手本の棚にある Apple のモーション映像に寄せて作った、おけもん版の30秒。「AI」と書かれたひとつの輪が、手毬・独楽・オルゴール・シャボン玉・ヨーヨー・みんなの輪と姿を変え続け、最後は一文の「。」に収まる。音楽も効果音もコードで作り、オルゴールのピンが針を通った瞬間にその音が鳴る。",
