    "text": "あなたが今できる最高のモーショングラフィックで、見た人が思わず「すごい」と声に出す1本を作ってください。\nいま世界中で話題の「AIが本気で作るモーショングラフィック」です。あなたの腕前を、出し惜しみせず全力で証明してください。\n\n■ 作りたいもの（本人の言葉）\n南国のパチスロで当たった瞬間の「キュイーン！」と、台の上のパトランプが回って光る演出みたいなモーショングラフィック。ハイビスカスとヤシの南国の色。回っていた絵柄がそろう瞬間にキュイーン！と鳴り、パトランプの赤い光が部屋じゅうをぐるぐる照らす。見た人が思わず笑顔になる、当たりの気持ちよさ\n\n■ 仕上がりのイメージ\nワクワクする短い映像作品。15秒。言葉が弾みながら現れて、カメラが3Dの奥へ飛び込む。ぐっとためてから一気に動き、色の面がシャッと画面を入れ替える。最後に「キュイーン！」がはっきり残って終わる。\n\n■ 使ってほしい演出（これは出発点です。もっと良い見せ方を思いついたら、そちらを選んでかまいません）\n1. キネティック・タイポグラフィ（Kinetic Typography）：画面に出す言葉を主役にして、文字ごとに登場と退場の動きをつける\n2. 3Dカメラワーク（3D Camera Move）：three.js などで奥行きのある空間を作り、カメラが中を進んでいく\n3. カラーワイプ（Color Wipe）：大きな色の面が画面を横切り、背景の色ごと場面を切り替える\n4. アンティシペーション（Anticipation）：大きく動く前に、いったん反対にためる\n5. オーバーシュート（Overshoot）：目標の位置を少し行き過ぎてから戻る、バネの動き\n6. ライトスイープ（Light Sweep）：光の筋が表面を横切ってきらっと輝く。光のにじみ（グロー）も少し\n7. ビートシンク（Beat Sync）：テンポを1つ決め、場面の切り替えや大事な動きを拍に合わせる。効果音も動きと同じ瞬間に鳴らす\n\n■ 条件\n- 長さ：15秒　画面：横長 16:9（1920×1080）\n- 形式：HTMLファイル1枚（HTML・CSS・JavaScriptをすべてこの中にまとめる）。今いる作業フォルダに motion.html として保存し（同じ名前があれば motion-2.html のように番号をつける）、できたらブラウザで開く（Mac なら open コマンド）\n- 再生：最後まで行ったら「もう一度見る」ボタンを出す\n- 外部のライブラリを使う時は CDN から読み込む（three.js など）。フォントはパソコンに入っている日本語フォントを使う\n- 時間の管理：すべての動きを1本のタイムライン（経過時間から各場面の状態を計算する形）で管理し、コマ落ちしても時間どおりに進むようにする\n- 音：Web Audio API で、BGM（テンポ 124BPM 前後）と効果音をコードだけで作る。ブラウザの決まりで最初は音が出ないので、最初の画面に大きな「▶ 音つきで再生」ボタンを置き、押したら映像と音を同時に始める。大事な動きと効果音は同じ瞬間に\n- 画面に出す言葉：「キュイーン！」（どれも一字一句そのまま使う）\n- 色：明るい白に、朱赤と紺、ひとさじの黄色（例：#FFF8F0 #FF5A36 #1E2A78 #FFC93C）\n- 文字：日本語は読みやすい太さのフォントで。小さすぎる文字は使わない\n\n■ いちばん大事なこと\n- いちばん大事なのは「作りたいもの（本人の言葉）」。上の『仕上がりのイメージ』『使ってほしい演出』『色』が本人の言葉と食い違うところは、本人の言葉を優先する\n- 演出を並べるだけにしない。ひとつの芯のアイデア（たとえば最初に出た形が最後まで姿を変え続ける）で、全部の場面をつなぐ\n- その芯は、説明がなくても画面を見るだけで伝わるようにする\n- 場面の切れ目はパッと切らず、前の場面の形を次の場面へ受け渡してつなぐ\n- 動きは等速にしない。加速・減速（イージング）と、止める瞬間（間）をつける\n- キャラクターや動物の絵をコードで描かない。図形・文字・模様・光・3Dの形で表現する（写真やイラストのファイルを渡された時だけ、それを使う）\n\n作り始める前に、芯のアイデアと場面の流れを3行で書き出してから作ってください。\n完成したら、使った演出と、芯のアイデアを1行ずつ教えてください。",
    "note": "アプリの注文書から（おけもんのお題を言葉にして組んだ。アプリが「キュイーン」「パトランプ」「モーショングラフィック」を読み違えていたのを直してから、作り直した注文書）。お手本は世界の1本ではなく、パチスロの「当たりの一音→パトランプが回る」という型。実機の映像・音・ロゴ・機種名は使っていない。作ったのは Claude Code（Opus 5.5）で、動画への書き出しは HyperFrames（HTMLを動画にする道具）"
