    "text": "あなたが今できる最高のモーショングラフィックで、見た人が思わず「すごい」と声に出す1本を作ってください。\nいま世界中で話題の「AIが本気で作るモーショングラフィック」です。あなたの腕前を、出し惜しみせず全力で証明してください。\n\n■ 作りたいもの（本人の言葉）\n架空の町の小さな図書館の「好きなものを1つ教えて」ポストの告知：夜の窓辺から紙飛行機が飛び、点線を引いて町の上を渡って図書館の屋根へ。本・音楽・海・パン・雨・星が0.5秒ずつクレヨン調で並び、最後にハートに集まって「すきなものを、1つ教えてください」。人やキャラは描かず、窓の明かりと紙飛行機で話を運ぶ\n\n■ お手本（この1本のテンポ・文字・切り替えに寄せる）\n- お手本：紙飛行機で「好きなものは？」と聞く、クレヨン絵本のようなアニメ（全コマを JavaScript で描いた）（Kevin Ngo） https://x.com/kevin_t_ngo/status/2102437977435893771\n- 特徴：クレヨンの塗りと、ちぎった紙のふちの手ざわり／ノートに手書きの字が1語ずつ書かれていく／紙飛行機が点線を引いて、場面から場面へ話を運ぶ／好きなものを0.5秒ずつ、背景の色を替えて次々に\n- 動画が見られなくても大丈夫。上の特徴に寄せて作る。お手本の色・ロゴ・言葉・キャラはそのまま使わず、「作りたいもの」に置きかえる\n- 作業フォルダにお手本のスクリーンショットがあれば、それも見て寄せる\n\n■ 仕上がりのイメージ\nかわいく、あたたかい告知。15秒。夜の静けさの中で、光の粒が集まっては弾けて、切り抜いた紙がぺたぺた重なる。ぽよんとつぶれて伸び、前の場面の形が、そのまま次の場面になる。最後にタイトルと日付がはっきり読める形で止まる。\n\n■ 使ってほしい演出（これは出発点です。もっと良い見せ方を思いついたら、そちらを選んでかまいません）\n1. パーティクル（Particle Animation）：小さな粒（光・紙吹雪・星）が集まって形になり、また散る\n2. カットアウト・アニメーション（Cutout Animation）：紙を切り抜いたような形が重なり、影つきで貼られたり剥がれたりする\n3. ハンドライティング・アニメーション（Handwriting Animation）：墨の筆が書き順どおりに漢字や言葉を書く。入りと払いの太さの変化、かすれも表現する\n4. マッチカット（Match Cut）：場面の切り替えでカットせず、前の場面の形を次の場面の部品へ受け渡す\n5. スクワッシュ＆ストレッチ（Squash and Stretch）：着地でつぶれ、飛ぶ時に伸びる。体積は保つ\n6. オーバーシュート（Overshoot）：目標の位置を少し行き過ぎてから戻る、バネの動き\n7. テクスチャオーバーレイ（Texture Overlay）：紙の繊維やうっすらした粒子を画面にのせて、手ざわりを出す\n8. アンビエントサウンド（Ambient Sound Design）：BGMは静かなパッドやオルゴールのような音にして、効果音は大事な瞬間だけ小さく鳴らす\n\n■ 条件\n- 長さ：15秒　画面：正方形 1:1（1080×1080）\n- 形式：HTMLファイル1枚（HTML・CSS・JavaScriptをすべてこの中にまとめる）。今いる作業フォルダに motion.html として保存し（同じ名前があれば motion-2.html のように番号をつける）、できたらブラウザで開く（Mac なら open コマンド）\n- 再生：最後まで行ったら「もう一度見る」ボタンを出す\n- 外部のライブラリを使う時は CDN から読み込む（three.js など）。フォントはパソコンに入っている日本語フォントを使う\n- 時間の管理：すべての動きを1本のタイムライン（経過時間から各場面の状態を計算する形）で管理し、コマ落ちしても時間どおりに進むようにする\n- 音：Web Audio API で、BGM（テンポ 97BPM 前後の静かな曲）と効果音をコードだけで作る。ブラウザの決まりで最初は音が出ないので、最初の画面に大きな「▶ 音つきで再生」ボタンを置き、押したら映像と音を同時に始める。大事な動きと効果音は同じ瞬間に（効果音は控えめに）\n- 画面に出す言葉：「好きなものを1つ教えて」「すきなものを、1つ教えてください」（どれも一字一句そのまま使う）\n- 色：夜の藍色に、月明かりのクリーム色と淡い青（かわいさを少し）（例：#0B1026 #1E2A5A #F6E7B0 #8FB8DE #E9ECF5）\n- 文字：日本語は読みやすい太さのフォントで。小さすぎる文字は使わない\n\n■ いちばん大事なこと\n- いちばん大事なのは「作りたいもの（本人の言葉）」。上の『仕上がりのイメージ』『使ってほしい演出』『色』が本人の言葉と食い違うところは、本人の言葉を優先する\n- 「すごい」は派手さのことではない。静かな作品なら、静けさと美しさで「すごい」と言わせる\n- 演出を並べるだけにしない。ひとつの芯のアイデア（たとえば最初に出た形が最後まで姿を変え続ける）で、全部の場面をつなぐ\n- その芯は、説明がなくても画面を見るだけで伝わるようにする\n- 場面の切れ目はパッと切らず、前の場面の形を次の場面へ受け渡してつなぐ\n- 動きは等速にしない。加速・減速（イージング）と、止める瞬間（間）をつける\n- キャラクターや動物の絵をコードで描かない。図形・文字・模様・光・3Dの形で表現する（写真やイラストのファイルを渡された時だけ、それを使う）\n\n作り始める前に、芯のアイデアと場面の流れを3行で書き出してから作ってください。\n完成したら、使った演出と、芯のアイデアを1行ずつ教えてください。",
